const messages:Record<Locale,Partial<Record<TextKey,string>>>={en,zh,de:{},fr:{},es:{},pt:{},ja:{},ko:{}};
for(const row of rows) extra.forEach((locale,i)=>{messages[locale][row[0]]=row[i+1];});
export function systemLocale(preferences:readonly string[]):Locale{
 for(const value of preferences){const prefix=value.toLowerCase().split(/[-_]/)[0];if(localeChoices.some(x=>x.id===prefix))return prefix as Locale;}
 return "en";
}
export function translate(locale:Locale,key:TextKey):string{return messages[locale][key]??en[key];}
export function coverage(locale:Locale):{translated:number;total:number}{
 const keys=Object.keys(en) as TextKey[];
 return {translated:keys.filter(k=>typeof messages[locale][k]==="string").length,total:keys.length};
}
